package practice;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import java.util.PriorityQueue;

/** The batch scheduler's queue: the worker always takes the job that is due soonest. */
public class JobQueue {

    public record Job(String name, Instant due) {}

    private final PriorityQueue<Job> queue = new PriorityQueue<>(Comparator.comparing(Job::due));

    public void submit(Job job) {
        queue.add(job);
    }

    /** Called by the worker: removes and returns the job due soonest. */
    public Optional<Job> next() {
        return Optional.ofNullable(queue.poll());
    }

    public int size() {
        return queue.size();
    }

    /** For the dashboard: the k jobs due soonest, soonest first, without taking them off the queue. */
    public List<Job> upcoming(int k) {
        PriorityQueue<Job> copy = new PriorityQueue<>(queue);
        List<Job> soonest = new ArrayList<>();
        while (soonest.size() < k && !copy.isEmpty()) soonest.add(copy.poll());
        return soonest;
    }
}

package practice;

import java.time.Instant;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            Instant eight = Instant.parse("2026-05-04T08:00:00Z");
            JobQueue queue = new JobQueue();
            queue.submit(new JobQueue.Job("backup", eight.plusSeconds(60L * 45)));
            queue.submit(new JobQueue.Job("reindex", eight.plusSeconds(60L * 10)));
            queue.submit(new JobQueue.Job("report", eight.plusSeconds(60L * 25)));
            queue.submit(new JobQueue.Job("cleanup", eight.plusSeconds(60L * 5)));
            System.out.println("next up (2): " + queue.upcoming(2).stream().map(JobQueue.Job::name).toList());
            System.out.println("next up (9): " + queue.upcoming(9).stream().map(JobQueue.Job::name).toList());
            System.out.println("still queued: " + queue.size());
            System.out.println("worker takes: " + queue.next().map(JobQueue.Job::name).orElse("nothing"));
            System.out.println("empty queue: " + new JobQueue().upcoming(3));
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

